from heapq import heapify, heappop, heappush

class Solution:
    def mergeKLists(
        self, lists: list[ListNode | None]
    ) -> ListNode | None:
        heap = [
            (node.val, idx, node)
            for idx, node in enumerate(lists)
            if node is not None
        ]
        heapify(heap)

        dummy = tail = ListNode()

        while heap:
            _, idx, node = heappop(heap)
            tail.next = node
            tail = node

            nxt = node.next
            if nxt is not None:
                heappush(heap, (nxt.val, idx, nxt))

        return dummy.next
